-- dunkirk_1940 開發庫寫入（tools/battles/write_battle_sql.py 產生；只 INSERT，單一交易由呼叫端包住）
DO $$ BEGIN IF EXISTS (SELECT 1 FROM battle_profiles WHERE slug = 'dunkirk_1940') THEN RAISE EXCEPTION 'battle % already exists; not overwriting', 'dunkirk_1940'; END IF;
